+// selectTask resolves explicit IDs without ever falling back to the current task.
+func selectTask(state *hookState, taskID []string) (*hookState, string, error) {
+	if len(taskID) == 0 || taskID[0] == "" || taskID[0] == state.Task {
+		return state, "", nil
+	}
+	previous := state.Past[taskID[0]]
+	if previous == nil {
+		return nil, "", fmt.Errorf("unknown task ID: %s", taskID[0])
+	}
+	if previous.Completed {
+		return previous, "already_reported", nil
+	}
+	if state.Pending != previous.Task {
+		return previous, "superseded", nil
+	}
+	return previous, "", nil
